head.script:
/*
 * 화면 동작
 * 1. 화면 로딩시 공통코드(회사속성·명의개서회사)를 조회하고 초기값(국적 대한민국)을 설정
 * 2. 국가코드 팝업 선택에 따라 국내/외국 입력 항목(법인·사업자번호, 우편번호, 영문주소, 전화 칸수)을 전환
 * 3. 법인/사업자등록번호 미등록 체크시 미등록사유 팝업으로 사유·통보예정일을 입력
 * 4. 결산월 셀렉트박스를 동적으로 추가/삭제하고 저장 전 필수·중복을 검증
 * 5. 아이디 중복확인(서브미션), 첨부파일(최대 5개·총 100MB), 개인정보 동의 3종 확인 후 저장(신청)
 *
 * 구성
 * 1. 발행기관 기본정보 입력 테이블 — 국적/명칭/법인·사업자번호/주소/연락처/결산월(동적) 등
 * 2. 담당자·신청자 정보, 첨부파일 그리드(grd_files·dlt_files), 개인정보 동의, 저장/취소 버튼
 *
 * 담긴 패턴
 * - 세션 사용자 정보 읽기 ($c.session.getUserInfo)
 * - 공통코드 셀렉트박스 ($c.data.setCommonCode) + 조회 후 코드 목록 가공
 * - 팝업 호출/결과 수신 ($c.win.openPopup — 국가코드·우편번호·미등록사유)
 * - 동적 서브미션 async/await ($c.sbm.executeDynamic — 아이디 중복확인)
 * - UDC 일괄 파일 저장 (udcSaver.save/attachFile/detachFile — /cm/udc/bulkFileSaver.xml)
 * - 진입점 try/catch 오류 처리 ($c.exception.handleError — code-convention §오류 처리)
 */


///////// 1. 변수 및 선언 영역 ///////// 

scwin.usrTpCd = $c.session.getUserInfo("usrTpCd");
scwin.sbxList = {};      // 동적 결산월 셀렉트박스 컴포넌트 목록 (key: "sbx_acntClsMm" + n)
scwin.sbxCount = 0;      // 동적 결산월 셀렉트박스 개수


///////// 2. 초기화 영역 ///////// 

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 08. 28
 * @description 페이지로드 — 초기화 함수 호출
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
	// 진입점 표준 오류 처리 — code-convention §오류 처리
	try {
		await scwin.init();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDINF05000.onpageload" });
	}
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 08. 28
 * @description 초기화 — 사용자 구분/초기 국적 설정, 공통코드 조회, 결산월 1개 생성, 데모 데이터 세팅
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
	// 사용자 구분코드 세팅
	dma_reg.set("usrAcntTpCd", scwin.usrTpCd);

	// 초기 국적 대한민국 세팅
	dma_reg.set("cntrCd", 410);

	ipt_cntrNm.setValue("대한민국");

	await scwin.comboSet();

	await scwin.addAcntClsMm();

	scwin.testSet();
};

/**
 * @method
 * @name scwin.comboSet
 * @author Inswave
 * @date 2026. 08. 28
 * @description 공통코드 조회(회사속성·명의개서회사) 및 조회 후 코드 목록 가공
 *   — 명의개서회사 "0" 행 제거, 회사속성 1·2 표시명 교체
 * @param
 * @returns
 * @hidden N
*/
scwin.comboSet = async function () {
	// 공통코드 설정
	const codeOptions = [
		{
			code: ["COM_ATTR_TP_CD", "TRANSSTK_AGNT_CD"],	// 회사속성 , 명의개서회사
			firstRow: ["", ""],
			compID: ["cmb_COM_ATTR_TP_CD", "rdo_transstkAgntCd"]
		}
	];

	await $c.data.setCommonCode(codeOptions);

	if (dlt_commonCode_TRANSSTK_AGNT_CD___rdo_transstkAgntCd.getCellData(0, "cdVal") === "0") {
		$c.cp.removeRow(dlt_commonCode_TRANSSTK_AGNT_CD___rdo_transstkAgntCd, 0);
	}

	for (let i = 0; i < dlt_commonCode_COM_ATTR_TP_CD___cmb_COM_ATTR_TP_CD.getTotalRow(); i++) {
		if (dlt_commonCode_COM_ATTR_TP_CD___cmb_COM_ATTR_TP_CD.getCellData(i, "cdVal") === "1") {
			dlt_commonCode_COM_ATTR_TP_CD___cmb_COM_ATTR_TP_CD.setCellData(i, "cdValNm", "주식회사");
		} else if (dlt_commonCode_COM_ATTR_TP_CD___cmb_COM_ATTR_TP_CD.getCellData(i, "cdVal") === "2") {
			dlt_commonCode_COM_ATTR_TP_CD___cmb_COM_ATTR_TP_CD.setCellData(i, "cdValNm", "증권투자회사");
		}
	}
};

