///////// 3. 컴포넌트 이벤트 영역 ///////// 

/**
 * @method
 * @name scwin.btn_cntrNm_onclick
 * @author Inswave
 * @date 2026. 08. 28
 * @description 국가코드 조회 버튼 클릭 — 국가코드 팝업 호출 후 선택 결과 반영
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_cntrNm_onclick = async function (e) {
	try {
		const options = {
			id: "cntrPop",
			width: "900",
			height: "750",
		};

		const result = await $c.win.openPopup("/ui/inf/comm/ULDINF90100.xml", options);

		scwin.cntrAfterSet(result);
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDINF05000.btn_cntrNm_onclick" });
	}
};

/**
 * @method
 * @name scwin.btn_zipcd_onclick
 * @author Inswave
 * @date 2026. 08. 28
 * @description 우편번호 조회 버튼 클릭 — 국내 국적만 우편번호 팝업 호출
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_zipcd_onclick = async function (e) {
	try {
		const cntrCd = ipt_cntrCd.getValue();
		if (cntrCd === "410") {
			// 팝업 호출
			await scwin.openZipcdPopup();
		} else if ($c.util.isEmpty(cntrCd)) {
			await $c.win.alert("국가코드가 없습니다.");
			ipt_cntrCd.focus();
		} else {
			await $c.win.alert("외국국적의 발행기관은 우편번호를 선택할 수 없습니다.");
		}
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDINF05000.btn_zipcd_onclick" });
	}
};

/**
 * @method
 * @name scwin.chx_regNot_onviewchange
 * @author Inswave
 * @date 2026. 08. 28
 * @description 법인/사업자등록번호 미등록 체크 변경 — 체크 시 번호 초기화·비활성화 후 미등록사유 팝업 호출
 * @param {Object} info 체크 변경 정보
 * @returns
 * @hidden N
*/
scwin.chx_regNot_onviewchange = function (info) {
	if (info.checked) {
		ipt_corpRegNo1.setValue("");
		ipt_corpRegNo2.setValue("");
		ipt_corpRegNo.setValue("");
		ipt_bzRegNo1.setValue("");
		ipt_bzRegNo2.setValue("");
		ipt_bzRegNo3.setValue("");
		ipt_bzRegNo.setValue("");

		// 법인,사업자등록번호 비활성화
		scwin.setCorpRegBzRegDisabled(true);
		scwin.popNonRegRsn();
	} else {
		// 법인,사업자등록번호 활성화
		scwin.setCorpRegBzRegDisabled(false);

		notiSchdlDd.setValue("");
		nregRsn.setValue("");
	}
};

/**
 * @method
 * @name scwin.chx_splitComNm_onviewchange
 * @author Inswave
 * @date 2026. 08. 28
 * @description 분할/상호변경 이력 체크 변경 — 체크 시 입력 영역 표시, 해제 시 입력값 초기화 후 숨김
 * @param {Object} info 체크 변경 정보
 * @returns
 * @hidden N
*/
scwin.chx_splitComNm_onviewchange = function (info) {
	if (info.checked) {
		div_split_com.setStyle("display", "block");
		chx_splitComNm.setValue("Y");
	} else {
		// 입력값 초기화
		ipt_bfsplitComNm.setValue("");
		ica_chgApplDd1.setValue("");
		ica_chgApplDd2.setValue("");
		ipt_isurNm1.setValue("");
		ipt_isurNm2.setValue("");
		chx_splitComNm.setValue("N");

		div_split_com.setStyle("display", "none");
	}
};

/**
 * @method
 * @name scwin.sbx_isurEngNm_onviewchange
 * @author Inswave
 * @date 2026. 08. 28
 * @description 영문명 회사속성 선택 변경 — 선택값을 영문명 속성 입력란에 반영(기타는 직접입력 활성)
 * @param {Object} info 선택 변경 정보
 * @returns
 * @hidden N
*/
scwin.sbx_isurEngNm_onviewchange = function (info) {
	const temp = sbx_isurEngNm.getValue();
	if (temp !== "" && temp !== "7") {
		ipt_isurEngNm2.setValue(sbx_isurEngNm.getText());

		// 직접입력 비활성
		ipt_isurEngNm2.setReadOnly(true);

	} else if (temp === "7") {
		ipt_isurEngNm2.setValue("");
		// 직접입력 활성
		ipt_isurEngNm2.setReadOnly(false);
		ipt_isurEngNm2.focus();

	} else if (temp === "") {
		ipt_isurEngNm2.setValue("");
		// 직접입력 비활성
		ipt_isurEngNm2.setReadOnly(true);
	}
};

/**
 * @method
 * @name scwin.cmb_COM_ATTR_TP_CD_onviewchange
 * @author Inswave
 * @date 2026. 08. 28
 * @description 회사속성 선택 변경 — ETF 계열 여부에 따른 법인/사업자번호 활성화 제어
 * @param {Object} info 선택 변경 정보
 * @returns
 * @hidden N
*/
scwin.cmb_COM_ATTR_TP_CD_onviewchange = function (info) {
	scwin.checkETF(info);
};

/**
 * @method
 * @name scwin.btn_checkUserId_onclick
 * @author Inswave
 * @date 2026. 08. 28
 * @description 아이디 중복확인 버튼 클릭
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_checkUserId_onclick = async function (e) {
	try {
		await scwin.checkUsrId();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDINF05000.btn_checkUserId_onclick" });
	}
};

/**
 * @method
 * @name scwin.btn_addAcntClsMm_onclick
 * @author Inswave
 * @date 2026. 08. 28
 * @description 결산월 추가 버튼 클릭
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_addAcntClsMm_onclick = function (e) {
	scwin.addAcntClsMm();
};

/**
 * @method
 * @name scwin.btn_delAcntClsMm_onclick
 * @author Inswave
 * @date 2026. 08. 28
 * @description 결산월 삭제 버튼 클릭 — 마지막 결산월 셀렉트박스 제거
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_delAcntClsMm_onclick = function (e) {
	gen_list.removeChild(--scwin.sbxCount);
};

/**
 * @method
 * @name scwin.btn_addRow_onclick
 * @author Inswave
 * @date 2026. 08. 28
 * @description 첨부파일 행 추가 버튼 클릭 — 최대 5개 제한
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_addRow_onclick = async function (e) {
	try {
		if (dlt_files.getRowCount() >= 5) {
			await $c.win.alert("파일업로드는 5개까지만 가능합니다.");
			return;
		}
		await scwin.addFileRow();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDINF05000.btn_addRow_onclick" });
	}
};

/**
 * @method
 * @name scwin.btn_delRow_onclick
 * @author Inswave
 * @date 2026. 08. 28
 * @description 첨부파일 행 삭제 버튼 클릭 — 선택 행 파일 해제 후 행 삭제
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_delRow_onclick = async function (e) {
	try {
		const idx = grd_files.getFocusedRowIndex();
		if (idx < 0) {
			await $c.win.alert("삭제할 행을 선택하세요.");
			return;
		}

		udcSaver.detachFile(idx, dlt_files);
		dlt_files.removeRow(idx);
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDINF05000.btn_delRow_onclick" });
	}
};

/**
 * @method
 * @name scwin.grd_files_oncellclick
 * @author Inswave
 * @date 2026. 08. 28
 * @description 첨부파일 그리드 셀 클릭 — 파일선택/해제 버튼 처리
 * @param {Number} rowIndex 행 index
 * @param {Number} columnIndex 컬럼 index
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
*/
scwin.grd_files_oncellclick = function (rowIndex, columnIndex, columnId) {
	if (columnId === "btn_pick") {
		const uid = "MOD_" + new Date().getTime() + "_" + Math.floor(Math.random() * 10000);
		dlt_files.setCellData(rowIndex, "uid", uid);
		udcSaver.attachFile(rowIndex, dlt_files);
	} else if (columnId === "btn_clear") {
		udcSaver.detachFile(rowIndex, dlt_files);
	}
};

/**
 * @method
 * @name scwin.btn_reg_onclick
 * @author Inswave
 * @date 2026. 08. 28
 * @description 신청(저장) 버튼 클릭
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_reg_onclick = async function (e) {
	try {
		await scwin.save();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDINF05000.btn_reg_onclick" });
	}
};

/**
 * @method
 * @name scwin.btn_cancel_onclick
 * @author Inswave
 * @date 2026. 08. 28
 * @description 취소 버튼 클릭
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_cancel_onclick = async function (e) {
	try {
		await scwin.reqCancel();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDINF05000.btn_cancel_onclick" });
	}
};


///////// 4. 서브미션 콜백 영역 ///////// 

/**
 * @method
 * @name scwin.checkUsrId
 * @author Inswave
 * @date 2026. 08. 28
 * @description 아이디 중복확인 — 필수/길이(6~20)/영문+숫자 조합을 공통 검증(composition 규칙)으로
 *   확인 후 서버 조회(dma_checkIdRes 바인딩). ※ 길이 위반 문구는 공통 표준(최소/최대길이) 문구로 표시
 * @param
 * @returns
 * @hidden N
*/
scwin.checkUsrId = async function () {
	// 아이디 검증 — 필수/길이(6~20)/영문+숫자 조합 (validate 공통 규칙)
	const options = {
		validateType : "alert",
		checkType : "single",
		focus : true,
		fields : {
			ipt_integUsrId : { required : true, minLength : 6, maxLength : 20,
			                   composition : { value : "engNum", message : "아이디는 영문+숫자의 조합이어야 합니다." },
			                   message : "아이디를 입력하세요.", name : "아이디" }
		}
	};

	if (!await $c.validate.validateDataCollect(grp_content, options)) {
		return;
	}

	dma_checkIdReq.set("integUsrId", ipt_integUsrId.getValue());

	const sbmOptions = {
		id: "checkId",
		action: "/api/isin/corp/corpNew/usrId-search",
		method: "get",
		ref: "dma_checkIdReq",
		target: "dma_checkIdRes=body"
	};

	await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 08. 28
 * @description 저장(신청) 처리 — 결합 필드 생성 → 검증(dataValidation) → 이메일/첨부/동의 확인 →
 *   확인 후 UDC 일괄 파일 저장(udcSaver.save)
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
	// 국내기업의 회사,담당자,신청자 전화번호/팩스번호 생성
	if (ipt_cntrCd.getValue() === '410') {
		ipt_telNo.setValue(ipt_telNo1.getValue() + "-" + ipt_telNo2.getValue() + "-" + ipt_telNo3.getValue());
		ipt_chrgTelNo.setValue(ipt_chrgTelNo1.getValue() + "-" + ipt_chrgTelNo2.getValue() + "-" + ipt_chrgTelNo3.getValue());
		ipt_encrypCellphoneNo.setValue(ipt_encrypCellphoneNo1.getValue() + "-" + ipt_encrypCellphoneNo2.getValue() + "-" + ipt_encrypCellphoneNo3.getValue());
		ipt_chrgFaxNo.setValue(ipt_chrgFaxNo1.getValue() + "-" + ipt_chrgFaxNo2.getValue() + "-" + ipt_chrgFaxNo3.getValue());
	}
	if (ipt_encrypChrgEmail1.getValue().trim().length > 0 && ipt_encrypChrgEmail2.getValue().trim().length > 0) {
		ipt_encrypChrgEmail.setValue(ipt_encrypChrgEmail1.getValue() + "@" + ipt_encrypChrgEmail2.getValue());
	}

	// 발행기관영문명 + 회사속성 결합 — 검증 전에 결합해 공통 검증(①)이 결합 필드 길이를 검사하게 한다
	ipt_isurEngNm.setValue(ipt_isurEngNm1.getValue() + " " + ipt_isurEngNm2.getValue());

	// 저장전 체크
	if (!await scwin.dataValidation()) {
		return;
	}

	// 이메일 형식·개인정보 동의 3종 검사는 공통 검증(dataValidation ①)으로 이동

	// 파일 첨부 갯수 확인
	if (!await scwin.checkLineFile()) {
		return;
	}

	// 첨부파일 크기 체크(전체 100MB) — $c.util.checkFileTotalSize 공통함수 (dataList 행을 size 객체로 전달)
	const sizeRst = $c.util.checkFileTotalSize(dlt_files.getAllJSON().map(function (r) { return { size : r.fileSize }; }), 100);
	if (!sizeRst.valid) {
		await $c.win.alert(sizeRst.message);
		return;
	}

	// 발행기관 정보변경 결산월 세팅
	for (let i = 1; i < scwin.sbxCount + 1; i++) {
		dma_reg.set("acntclsMm" + i, scwin.sbxList["sbx_acntClsMm" + i].getValue());
	}

	if (await $c.win.confirm("입력된 이메일을 확인해주세요.\n\n이메일 : " + ipt_encrypChrgEmail.getValue() + "\n\n신청하시겠습니까?")) {
		await udcSaver.save({
			dataMap: dma_reg,
			dataMapId: "dto",
			dataList: dlt_files,
			dataListId: "fileMstDescr",
			saveUrl: "/api/isin/corp/corpNew/corpNew-proc",
			onValidate: function (row) {

			},
			onSuccess: function (res) {
				$c.win.success($c.data.getMessage("com_crud_0129"));
			}
		});
	}
};


