 * @name scwin.popupCallback
 * @author Inswave
 * @date 2026. 08. 28
 * @description 미등록사유 팝업 결과 처리 — 빈값(닫기)이면 체크 해제·번호 입력 활성화, 아니면 사유/통보예정일 반영
 * @param {Object} arg 팝업 반환값 ({ notiSchdlDd, nregRsn })
 * @returns
 * @hidden N
*/
scwin.popupCallback = function (arg) {
	// 팝업창에서 닫기버튼 눌렀을때(빈값이 오면) 빈값 세팅 후 체크해제 처리
	if ($c.util.isEmpty(arg.notiSchdlDd) && $c.util.isEmpty(arg.nregRsn)) {
		chx_regNot.setSelectedIndex(0);
		// 법인,사업자등록번호 활성화
