/**
 * @method
 * @name scwin.cntrAfterSet
 * @author Inswave
 * @date 2026. 08. 28
 * @description 국가코드 팝업 선택 결과 반영 — 주소/번호 초기화 후 국내(410)/외국에 따라
 *   입력 항목 활성화와 전화번호 칸수(3칸/1칸)를 전환
 * @param {Object} result 팝업 반환값 ({ cntrCd, cntrNm })
 * @returns
 * @hidden N
*/
scwin.cntrAfterSet = function (result) {
	ipt_cntrCd.setValue(result.cntrCd);
	ipt_cntrNm.setValue(result.cntrNm);

	// 본점소재지 영문
	ipt_engAddr.setValue("");
	ipt_engDtlAddr.setValue("");

	// 법인번호
	ipt_corpRegNo1.setValue("");
	ipt_corpRegNo2.setValue("");
	ipt_corpRegNo.setValue("");

	// 사업자번호
	ipt_bzRegNo1.setValue("");
	ipt_bzRegNo2.setValue("");
	ipt_bzRegNo3.setValue("");
	ipt_bzRegNo.setValue("");

	// 우편번호
	ipt_zipcd.setValue("");
	// 주소
	ipt_addr.setValue("");
	// 상세주소
	ipt_dtlAddr.setValue("");

	if (result.cntrCd === "410") {
		ipt_engAddr.setDisabled(true);
		scwin.setCorpRegBzRegDisabled(false);
		ipt_zipcd.setDisabled(false);
		ipt_dtlAddr.setDisabled(false);

		// 대표전화 전화번호 휴대전화번호 3칸짜리로 변경
		grp_telNo1.addClass("hide");
		grp_telNo2.removeClass("hide");

		grp_chrgTelNo1.addClass("hide");
		grp_chrgTelNo2.removeClass("hide");

		grp_cellphoneNo1.addClass("hide");
		grp_cellphoneNo2.removeClass("hide");

		grp_chrgFaxNo1.addClass("hide");
		grp_chrgFaxNo2.removeClass("hide");
	} else {
		// 본점소재지 영문 활성, 법인/사업자/우편번호/상세주소 비활성
		// 대표전화 전화번호 휴대전화번호 1칸짜리로 변경
		ipt_engAddr.setDisabled(false);
		scwin.setCorpRegBzRegDisabled(true);
		ipt_zipcd.setDisabled(true);
		ipt_dtlAddr.setDisabled(true);

		grp_telNo1.removeClass("hide");
		grp_telNo2.addClass("hide");

		grp_chrgTelNo1.removeClass("hide");
		grp_chrgTelNo2.addClass("hide");

		grp_cellphoneNo1.removeClass("hide");
		grp_cellphoneNo2.addClass("hide");

		grp_chrgFaxNo1.removeClass("hide");
		grp_chrgFaxNo2.addClass("hide");
	}
};

