/**
 * @method
 * @name scwin.checkCorpRegNo
 * @author Inswave
 * @date 2026. 08. 28
 * @description 법인등록번호 검증번호(check digit) 체크 (※ 현재 미호출 — 원본 화면 이관분.
 *   공통 규칙 format:corpNum($c.validate)으로 대체 가능)
 * @param
 * @returns {Boolean} 검증 통과 여부
 * @hidden N
*/
scwin.checkCorpRegNo = async function () {
	const no = ipt_corpRegNo.getValue();

	if (no.length !== 13) {
		await $c.win.alert("법인등록번호를 확인하여 주세요" + "\n" + "법인등록번호 Length Error");
		return false;
	}

	const chkDigit = no.substring(12, 13);
	const corpRegNo = no.substring(0, 12);

	let sum = 0;
	for (let i = 0; i < 12; i++) {
		sum += corpRegNo.substring(i, i + 1) * ((i % 2 === 0) ? 1 : 2);   // 가중치 1,2 반복
	}

	const chk = (10 - (sum % 10)) % 10;

	if (Number(chkDigit) !== chk) {   // 검증번호 비교 — 문자(substring)/숫자 타입 통일 후 엄격 비교
		await $c.win.alert("법인등록번호에 오류가 있습니다.");
		return false;
	}

	return true;
};

/**
 * @method
 * @name scwin.moveCorpRegNoFocus
 * @author Inswave
 * @date 2026. 08. 28
 * @description 법인등록번호 분리 입력 포커스 자동이동 (※ 현재 이벤트 미연결 — 원본 화면 이관분)
 * @param
 * @returns
 * @hidden N
*/
scwin.moveCorpRegNoFocus = async function () {
	const cntrCd = ipt_cntrCd.getValue();
	if ($c.util.isEmpty(cntrCd)) {
		await $c.win.alert("국가코드가 없습니다.");
		ipt_cntrCd.focus();
	} else if (cntrCd === "410") {
		if (ipt_corpRegNo1.getValue().length === 6) {
			if (ipt_corpRegNo2.getValue().length !== 7) {
				ipt_corpRegNo2.focus();
			}
			if (ipt_corpRegNo2.getValue().length === 7) {
				ipt_corpRegNo1.focus();
			}
		}
	} else {
		await $c.win.alert("외국국적의 발행기관은 법인등록번호를 선택할 수 없습니다.");
	}
};

