/**
 * @method
 * @name scwin.checkETF
 * @author Inswave
 * @date 2026. 08. 28
 * @description 회사속성 ETF 계열 체크 — 국내기업에서 (ETF·상장형수익증권·BDC)는 법인/사업자번호를
 *   비활성화하고 미등록사유 체크를 잠근다. BDC 중 기업성장투자회사(A)는 입력 대상.
 * @param {Object} obj 선택 변경 정보 (newSelectedIndex 참조)
 * @returns
 * @hidden N
*/
scwin.checkETF = function (obj) {
	// 국내기업일경우만 체크
	if (ipt_cntrCd.getValue() === "410") {
		const selIdx = String(obj.newSelectedIndex);   // 숫자로 전달될 수 있어 문자열로 통일 후 엄격 비교
		if (selIdx === "5" || selIdx === "7" || selIdx === "B") {
			ipt_corpRegNo1.setValue("");
			ipt_corpRegNo2.setValue("");
			ipt_corpRegNo.setValue("");
			ipt_bzRegNo1.setValue("");
			ipt_bzRegNo2.setValue("");
			ipt_bzRegNo3.setValue("");
			ipt_bzRegNo.setValue("");

			// 법인,사업자등록번호 비활성화
			scwin.setCorpRegBzRegDisabled(true);

			// 미등록사유 체크 박스 변경
			chx_regNot.setValue("false");
			notiSchdlDd.setValue("");
			nregRsn.setValue("");
			chx_regNot.setDisabled(true);
		} else {
			// 법인,사업자등록번호 활성화
			scwin.setCorpRegBzRegDisabled(false);

			// 미등록사유 체크 박스 변경
			chx_regNot.setDisabled(false);
		}
	}
};

/**
 * @method
 * @name scwin.dataValidation
 * @author Inswave
 * @date 2026. 08. 28
 * @description 저장 전 입력값 검증 — ① 공통 검증($c.validate.validateDataCollect: 정적 규칙 + 복합 조건
 *   동적 규칙(fields 동적 구성), includeUnbound 로 미바인딩 분리 입력 칸 포함)
 *   → ② 수작업 검증·상태 정리(실패 시 팝업 후속·동적 결산월·OR 조건, 번호 결합/초기화/플래그)
 * @param
 * @returns {Boolean} 검증 통과 여부
 * @hidden N
*/
scwin.dataValidation = async function () {
	// ① 공통 검증 — 단순 필수/길이/단일 참조 조건(requiredIf)/형식/중복확인(matchValue) 규칙
	//    includeUnbound : DataCollection 미바인딩 컴포넌트(분리 입력 칸·조합용 셀렉트박스)도
	//    컴포넌트 ID 규칙으로 검증한다 (표시명은 name 지정).
	const options = {
		validateType : "alert",  // alert(알림) | mark(req 클래스 마킹) | all(알림+마킹)
		checkType : "single",    // 첫 실패 즉시 중단 — 알림 순서는 화면 배치(DOM) 순
		focus : true,
		includeUnbound : true,   // 미바인딩 분리 입력 칸 포함
		fields : {
			ipt_cntrCd       : { required : true, name : "국가코드" },
			ipt_isurNm       : { required : true, maxLength : 80, name : "발행기관명" },
			ipt_isurAbbrv    : { required : true, maxLength : 40, name : "발행기관 한글약명" },
			ipt_isurEngNm1   : { required : true, message : "발행기관영문명을 입력하세요.", name : "발행기관영문명" },   // 미바인딩 분리 입력 첫 칸
			sbx_isurEngNm    : { required : true, message : "발행기관영문명의 '회사속성'을 선택하세요.", name : "영문명 회사속성" },   // 미바인딩 셀렉트박스
			ipt_isurEngNm    : { maxLength : 80, name : "발행기관영문명(회사속성 포함)" },   // save() 에서 결합 후 검사
			ipt_isurEngAbbrv : { required : true, maxLength : 40, name : "발행기관 영문약명" },
			cmb_COM_ATTR_TP_CD : { required : true, name : "회사속성" },

			// 국내(410)/외국 분기 — 참조 컴포넌트 단일 조건 (requiredIf equals/notEquals)
			ipt_addr       : { requiredIf : { compID : "ipt_cntrCd", equals : "410", message : "주소를 입력하세요." }, name : "주소" },
			ipt_dtlAddr    : { requiredIf : { compID : "ipt_cntrCd", equals : "410", message : "상세주소를 입력하세요." }, name : "상세주소" },
			ipt_engAddr    : { requiredIf : { compID : "ipt_cntrCd", notEquals : "410", message : "영문주소를 입력하세요." }, name : "영문주소" },
			ipt_engDtlAddr : { requiredIf : { compID : "ipt_cntrCd", notEquals : "410", message : "영문상세주소를 입력하세요." }, name : "영문상세주소" },
			ipt_telNo      : { requiredIf : { compID : "ipt_cntrCd", notEquals : "410", message : "대표전화를 입력하세요." }, name : "대표전화" },
			ipt_telNo1     : { requiredIf : { compID : "ipt_cntrCd", equals : "410", message : "대표전화를 입력하세요." }, name : "대표전화" },   // 국내 3칸 (미바인딩)
			ipt_telNo2     : { requiredIf : { compID : "ipt_cntrCd", equals : "410", message : "대표전화를 입력하세요." }, name : "대표전화" },
			ipt_telNo3     : { requiredIf : { compID : "ipt_cntrCd", equals : "410", message : "대표전화를 입력하세요." }, name : "대표전화" },

			ipt_ceoNm      : { required : true, name : "대표이사" },
			ipt_hpage      : { format : "urlNoProtocol", name : "홈페이지" },   // 'http://' 등 프로토콜 입력 방지
			ica_foundDd    : { required : true, name : "설립일" },
			rdo_transstkAgntCd : { required : true, name : "명의개서회사" },

			// 분할/상호변경 — 변경일 입력 시 구상호 필수 (체크 해제 시 값이 초기화되므로 무조건 선언해도 동작 동일)
			ipt_bfsplitComNm : { maxLength : 100, name : "분할전 법인명" },
			ipt_isurNm1    : { requiredIf : { compID : "ica_chgApplDd1", notEmpty : true, message : "구상호를 입력하세요." }, name : "구상호1" },
			ipt_isurNm2    : { requiredIf : { compID : "ica_chgApplDd2", notEmpty : true, message : "구상호를 입력하세요." }, name : "구상호2" },

			// 미등록사유/통보예정일 — 미등록 체크 시 필수 (미등록사유 팝업에서 입력되는 값)
			// ※ 원 수작업 검사의 "실패 시 사유 팝업 자동 호출"은 공통화로 제외 — 알림으로 대체
			nregRsn        : { requiredIf : { compID : "chx_regNot", equals : "true", message : "미등록 사유를 입력해 주세요" }, name : "미등록 사유" },
			notiSchdlDd    : { requiredIf : { compID : "chx_regNot", equals : "true", message : "통보예정일을 입력해 주세요" }, name : "통보예정일" },

			// 아이디 — 중복확인 여부는 matchValue(미입력도 실패) + focus 로 아이디 입력란 유도 (검증 명세 v3 §5)
			ipt_integUsrId : { required : true, name : "아이디" },
			ipt_newYn      : { matchValue : { value : "Y", message : "아이디 중복확인 여부를 확인하십시오." },
			                   focus : "ipt_integUsrId", name : "중복확인" },

			// 담당자 (국내 3칸 분리 입력은 미바인딩 — ② 에서 수작업, 외국 단일 칸은 결합 필드 규칙)
			ipt_chrgNm     : { required : true, name : "담당자이름" },
			ipt_belngDepNm : { required : true, name : "소속부서" },
			ipt_jobtitlNm  : { required : true, name : "직책" },
			ipt_encrypCellphoneNo : { requiredIf : { compID : "ipt_cntrCd", notEquals : "410", message : "담당자 휴대전화번호를 입력하세요." }, name : "담당자 휴대전화번호" },
			ipt_chrgTelNo  : { requiredIf : { compID : "ipt_cntrCd", notEquals : "410", message : "담당자 전화번호를 입력하세요." }, name : "담당자 전화번호" },
			// 국내 담당자 전화/휴대전화 3칸 (미바인딩 분리 입력)
			ipt_chrgTelNo1 : { requiredIf : { compID : "ipt_cntrCd", equals : "410", message : "담당자 전화번호를 입력하세요." }, name : "담당자 전화번호" },
			ipt_chrgTelNo2 : { requiredIf : { compID : "ipt_cntrCd", equals : "410", message : "담당자 전화번호를 입력하세요." }, name : "담당자 전화번호" },
			ipt_chrgTelNo3 : { requiredIf : { compID : "ipt_cntrCd", equals : "410", message : "담당자 전화번호를 입력하세요." }, name : "담당자 전화번호" },
			ipt_encrypCellphoneNo1 : { requiredIf : { compID : "ipt_cntrCd", equals : "410", message : "담당자 휴대전화번호를 입력하세요." }, name : "담당자 휴대전화번호" },
			ipt_encrypCellphoneNo2 : { requiredIf : { compID : "ipt_cntrCd", equals : "410", message : "담당자 휴대전화번호를 입력하세요." }, name : "담당자 휴대전화번호" },
			ipt_encrypCellphoneNo3 : { requiredIf : { compID : "ipt_cntrCd", equals : "410", message : "담당자 휴대전화번호를 입력하세요." }, name : "담당자 휴대전화번호" },
			// 회사담당자 이메일 2칸 (미바인딩 분리 입력) + 결합 필드 형식 검사(save() 에서 결합 후 — 실패 시 첫 칸 포커스)
			ipt_encrypChrgEmail1 : { required : true, message : "회사담당자 이메일을 입력하세요.", name : "회사담당자 이메일" },
			ipt_encrypChrgEmail2 : { required : true, message : "회사담당자 이메일을 입력하세요.", name : "회사담당자 이메일" },
			ipt_encrypChrgEmail  : { format : "email", focus : "ipt_encrypChrgEmail1", name : "회사담당자 이메일" },

			// 개인정보 동의 3종 — checked 는 미체크 값("0"·false)도 실패 (문구는 "…동의 해주세요." 표준)
			perInfo1 : { checked : true, name : "개인정보 처리방침 동의" },
			perInfo2 : { checked : true, name : "개인정보 수집·이용 동의" },
			perInfo3 : { checked : true, name : "표준코드 서비스 이용약관 동의" }
		}
	};

	// [동적 규칙] 법인/사업자등록번호·우편번호 — 미등록 체크 아님 × 국내(410) (× ETF 계열 아님)
	//  requiredIf 는 단일 참조 조건만 지원하므로 복합 조건은 여기서 판정해 규칙만 추가한다.
	//  ※ options 를 호출마다 새로 구성하므로 동적 속성이 다음 호출에 잔존하지 않는다.
	if (chx_regNot.getValue() !== "true" && ipt_cntrCd.getValue() === "410") {
		// (ETF, 상장형수익증권, BDC)는 법인번호와 사업자번호 없음 — BDC 중 기업성장투자회사(A)는 입력한다
		const comAttrTpCd = cmb_COM_ATTR_TP_CD.getValue();
		if (comAttrTpCd !== "5" && comAttrTpCd !== "7" && comAttrTpCd !== "B") {
			options.fields.ipt_corpRegNo1 = { required : true, fixLength : 6, message : "법인등록번호를 입력하세요.", name : "법인등록번호" };
			options.fields.ipt_corpRegNo2 = { required : true, fixLength : 7, message : "법인등록번호를 입력하세요.", name : "법인등록번호" };
			options.fields.ipt_bzRegNo1   = { required : true, fixLength : 3, message : "사업자등록번호를 입력하세요.", name : "사업자등록번호" };
			options.fields.ipt_bzRegNo2   = { required : true, fixLength : 2, message : "사업자등록번호를 입력하세요.", name : "사업자등록번호" };
			options.fields.ipt_bzRegNo3   = { required : true, fixLength : 5, message : "사업자등록번호를 입력하세요.", name : "사업자등록번호" };
		}
		options.fields.ipt_zipcd = { required : true, message : "우편번호를 입력하세요.", name : "우편번호" };
	}

	// [동적 규칙] 담당자 팩스 3칸 — 하나라도 입력 시 모두 필수 (all-or-none 그룹)
	if (ipt_cntrCd.getValue() === '410'
		&& (ipt_chrgFaxNo1.getValue().length > 0 || ipt_chrgFaxNo2.getValue().length > 0 || ipt_chrgFaxNo3.getValue().length > 0)) {
		options.fields.ipt_chrgFaxNo1 = { required : true, message : "담당자 팩스번호를 입력하세요.", name : "담당자 팩스번호" };
		options.fields.ipt_chrgFaxNo2 = { required : true, message : "담당자 팩스번호를 입력하세요.", name : "담당자 팩스번호" };
		options.fields.ipt_chrgFaxNo3 = { required : true, message : "담당자 팩스번호를 입력하세요.", name : "담당자 팩스번호" };
	}

	if (!await $c.validate.validateDataCollect(grp_content, options)) {
		return false;
	}

	// ② 수작업 검증·상태 정리 — 공통 규칙으로 표현 불가한 항목
	//    (실패 시 팝업 후속 처리, 동적 결산월, OR 복합 조건) + 검증 통과 후 상태 정리

	// 법인/사업자등록번호·우편번호 검사는 공통 검증(① 동적 규칙)으로 이동 —
	// 여기서는 검증 통과 후 상태 정리(번호 결합/초기화/미등록 플래그)만 수행한다
	if (chx_regNot.getValue() !== "true") {
		if (ipt_cntrCd.getValue() === "410") {
			ipt_corpRegNo.setValue(ipt_corpRegNo1.getValue() + ipt_corpRegNo2.getValue());
			ipt_bzRegNo.setValue(ipt_bzRegNo1.getValue() + ipt_bzRegNo2.getValue() + ipt_bzRegNo3.getValue());
		} else {
			ipt_corpRegNo1.setValue("");
			ipt_corpRegNo2.setValue("");

			ipt_bzRegNo1.setValue("");
			ipt_bzRegNo2.setValue("");
			ipt_bzRegNo3.setValue("");

			ipt_corpRegNo.setValue("");
			ipt_bzRegNo.setValue("");

			ipt_zipcd.setValue("");
		}
		chx_regNot.setValue("false");
	} else {
		ipt_corpRegNo1.setValue("");
		ipt_corpRegNo2.setValue("");
		ipt_bzRegNo1.setValue("");
		ipt_bzRegNo2.setValue("");
		ipt_bzRegNo3.setValue("");

		// 미등록사유/통보예정일 필수 검사는 공통 검증(① requiredIf)으로 이동
		chx_regNot.setValue("true");
	}

	// 주소(국내/외국)·대표이사·홈페이지·대표전화(국내 3칸 포함)·설립일 검사는 공통 검증(①)으로 이동

	// 결산월 필수 체크 (동적 생성 컴포넌트 — 공통 fields 로 선언 불가)
	for (let i = 1; i < scwin.sbxCount + 1; i++) {
		const acntClsMm = scwin.sbxList["sbx_acntClsMm" + i];
		if ($c.util.isEmpty(acntClsMm.getValue())) {
			await $c.win.alert("결산월을 선택해 주세요.");
			acntClsMm.focus();
			return false;
		}
	}

	// 결산월 중복 체크
	for (let i = 1; i <= scwin.sbxCount; i++) {
		const acntClsMm1 = scwin.sbxList["sbx_acntClsMm" + i];
		for (let j = scwin.sbxCount; j >= 1; j--) {
			const acntClsMm2 = scwin.sbxList["sbx_acntClsMm" + j];
			if (i !== j && acntClsMm1.getValue() !== '' && acntClsMm2.getValue() !== ''
				&& acntClsMm1.getValue() === acntClsMm2.getValue()) {
				await $c.win.alert("동일한 결산월이 존재합니다.\n결산월을 확인해주세요!");
				acntClsMm2.focus();
				return false;
			}
		}
	}

	// 회사속성·명의개서회사·분할전 법인명 길이·구상호 선행 조건·아이디/중복확인·담당자 기본정보
	// 검사는 공통 검증(①)으로 이동 — OR 복합 조건(아래)만 수작업 유지

	if (chx_splitComNm.getValue() === "Y") {
		if ($c.util.isEmpty(ipt_bfsplitComNm.getValue()) && $c.util.isEmpty(ica_chgApplDd1.getValue()) && $c.util.isEmpty(ica_chgApplDd2.getValue())) {
			await $c.win.alert("분할전 법인명 또는 상호변경이력정보를 입력하세요.");
			ipt_bfsplitComNm.focus();
			return false;
		}
	}

	// 국내 담당자 전화/휴대전화 3칸·팩스(all-or-none 동적 규칙)·이메일 2칸 검사는 공통 검증(①)으로 이동

	return true;
};

/**
 * @method
 * @name scwin.checkLineFile
 * @author Inswave
 * @date 2026. 08. 28
 * @description 저장 시 첨부파일 행에 파일이 모두 첨부되어 있는지 확인
 * @param
 * @returns {Boolean} 확인 통과 여부
 * @hidden N
*/
scwin.checkLineFile = async function () {
	for (let i = 0; i < dlt_files.getRowCount(); i++) {
		const fileName = dlt_files.getCellData(i, "fileName");

		if (fileName === "") {
			await $c.win.alert("첨부파일이 없습니다.\n첨부할 파일이 없으면 파일첨부를 삭제해 주세요");
			grd_files.setFocusedCell(i, "fileName", true);
			return false;
		}
	}

	return true;
};

/**
 * @method
 * @name scwin.reqCancel
 * @author Inswave
 * @date 2026. 08. 28
 * @description 신청 취소 처리 — 확인 후 입력값/첨부파일 초기화
 * @param
 * @returns
 * @hidden N
*/
scwin.reqCancel = async function () {
	if (await $c.win.confirm("신청을 취소하시겠습니까?")) {
		dma_reg.setEmptyValue();
		dlt_files.removeAll();
	}
};

/**
 * @method
 * @name scwin.addFileRow
 * @author Inswave
 * @date 2026. 08. 28
 * @description 첨부파일 행 추가 — 개인정보 삭제 확인 후 신규 행(uid 부여) 삽입
 * @param
 * @returns
 * @hidden N
*/
scwin.addFileRow = async function () {
	if (await $c.win.confirm("파일 첨부 시 주민등록번호 등 개인정보 삭제를 확인하셨습니까?")) {
		const uid = "NEW_" + new Date().getTime() + "_" + Math.floor(Math.random() * 10000);
		const newIdx = dlt_files.getRowCount();

		dlt_files.insertRow(newIdx, {
			fileName: "",
			fileDescr: ""
		});

		dlt_files.setCellData(newIdx, "uid", uid);
	}
};

/**
 * @method
 * @name scwin.addAcntClsMm
 * @author Inswave
 * @date 2026. 08. 28
 * @description 결산월 셀렉트박스 동적 추가 — 생성 컴포넌트를 sbxList 에 등록
 * @param
 * @returns
 * @hidden N
*/
scwin.addAcntClsMm = async function () {
	scwin.sbxCount++;
	const newKey = "sbx_acntClsMm" + scwin.sbxCount;
	const idx = gen_list.insertChild();

	scwin.sbxList[newKey] = gen_list.getChild(idx, "sbx_acntClsMm");
};
